#!/usr/bin/env bash
# usage: bash art/portraits/batch_cast.sh [name-filter]   (run from repo root)
# Derives every non-Moxie expression from that character's anchor, two requests at a time.
# Skips outputs that already exist; delete a raw file to regenerate it.
R=art/portraits/raw; F="${1:-}"
OPAL="Opal, a woman in her sixties with deep dark-brown skin, short silver-grey curly hair, half-moon reading glasses, gold hoop earrings, cream shirt collar, apricot-orange cable-knit shawl-collar cardigan with brown buttons, slate-grey work apron with brass buckles and two screwdrivers in the chest pocket, brass jeweller's loupe on a brown cord."
TOLLY="Tolliver, a lanky man in his late twenties with light tan skin, sandy-blond hair, round wire-rimmed glasses, white hard hat with a clip-on lamp pushed back on his head, yellow pencil behind his ear, periwinkle-blue zip survey jacket with white reflective bands, grey climbing harness straps with metal buckles, dark clipboard tablet held at his chest."
ARCH="The Archivist, a faceless machine: hooded housing of near-black violet metal with teal glowing rune grooves, two large three-spoke tape reels where eyes would be, one small round orange sensor lens between them, loose strands of magnetic tape hanging below, a thin teal halo ring carrying twelve small rectangular screens behind the head. Strictly frontal and symmetrical; same housing, hood, shoulders, rune layout, tape strands and halo layout as the input."
jobs=(
"opal_neutral_b|opal_dry|$OPAL|the expression only: one eyebrow raised high, eyes half-lidded, mouth perfectly flat, head tipped a few degrees as if naming a price. Chin still resting on her knuckles, glasses still pushed up on her forehead."
"opal_neutral_b|opal_amused|$OPAL|the expression only: one corner of the mouth lifted in a small dry smile, crow's-feet crinkling at the eyes, eyes warm and narrowed, looking slightly sideways. Chin still resting on her knuckles, glasses still pushed up on her forehead."
"opal_neutral_b|opal_worried|$OPAL|the expression and the hand: brows pinched together and raised in the middle, eyes wider and fixed ahead, lips parted mid-word. Her hand has dropped away from her chin and is pressed flat against her upper chest just above the apron (five fingers), head leaning very slightly forward. Glasses still pushed up on her forehead. She does not smile."
"opal_neutral_b|opal_soft|$OPAL|the expression and the hand: her reading glasses are taken off her forehead (no glasses on her head or face), her eyes are lowered, looking down at a small grey cassette tape held in her open palm, raised to chest height where her fist used to be (five fingers, the cassette small and simple with two reel holes), a quiet genuine closed-mouth smile, brows relaxed."
"tolly_neutral_a|tolly_earnest|$TOLLY|the expression only: bright open sincere smile showing upper teeth, eyes wide and keen behind the glasses looking toward the viewer, eyebrows raised, head tipped a little forward eagerly. Both hands still hold the tablet."
"tolly_neutral_a|tolly_flustered|$TOLLY|the expression and small details: glasses slipped halfway down his nose, eyebrows tilted up in alarm, eyes wide, a wobbly wavy uncertain mouth, one single large anime sweat drop on his temple, the hard hat tilted a little askew. Same pose, same head size and head position as the input; both hands still hold the tablet at the bottom edge exactly as in the input."
"tolly_neutral_a|tolly_impressed|$TOLLY|the expression only: mouth open in sincere quiet awe (a soft open oval, not comic), eyes wide and shining with one bright highlight each, eyebrows high, looking toward the viewer. Both hands still hold the tablet, lowered a little."
"archivist_idle_a|archivist_playback|$ARCH|a clearly visible, dramatic change of machine state - PLAYBACK. The twelve halo screens are no longer dark: every one is switched ON, glowing brightly, and shows a tiny simple flat silhouette of a girl with two pigtails standing, each screen in one flat colour, with the screen background filled in that bright flat colour and the girl silhouette dark on it, cycling red-pink, yellow, sky blue, green around the ring. Both tape reels are spinning backwards fast: the three spokes are replaced by blurred concentric spin streaks and bold curved speed lines arc around each reel. The orange sensor flares white-hot with a sharp four-point star flare. The teal rune light is brighter."
"archivist_idle_a|archivist_still|$ARCH|a clearly visible change of machine state - STILL, powered down. Remove every motion line near the reels: both reels are completely stopped. The orange sensor is nearly out: a small dull dark-red ember with no glow. All teal rune grooves and the halo ring are dimmed to a dull dark grey-teal, barely lit. Eleven halo screens stay dark; ONLY the single top-centre screen is switched on, glowing soft cream-white, showing one small simple dark cassette-tape icon (a rounded rectangle with two reel holes)."
)
run() { IFS='|' read -r a o keep chg <<<"$1"
  [ -n "$F" ] && [[ "$o" != *$F* ]] && return
  [ -s "$R/$o.png" ] && { echo "have $o"; return; }
  bash art/portraits/retry.sh "$R/$o.png" bash art/portraits/gen_expr.sh "$R/$a.png" "$R/$o.png" "$keep" "$chg"; }
i=0
for j in "${jobs[@]}"; do run "$j" & i=$((i+1)); [ $((i%2)) -eq 0 ] && wait; done; wait
